<?php
require_once dirname(__DIR__) . '/config.php';
require_admin();
$counts = $pdo->query("SELECT COUNT(*) AS total, SUM(booking_status = 'pending') AS pending, SUM(booking_status = 'confirmed') AS confirmed FROM bookings")->fetch();
$statement = $pdo->query('SELECT b.*, u.name AS guest_name, u.email, r.room_name FROM bookings b JOIN users u ON u.user_id = b.user_id JOIN rooms r ON r.room_id = b.room_id ORDER BY FIELD(b.booking_status, "pending", "confirmed", "cancelled"), b.booking_date DESC');
$bookings = $statement->fetchAll();
$pageTitle = 'Villa dashboard | SeaGlass Villa'; require dirname(__DIR__) . '/includes/header.php';
?>
<section class="dashboard-page wrap"><div class="page-heading"><div><p class="eyebrow">SeaGlass operations</p><h1>Reservations</h1><p>Review requests and keep your rooms up to date.</p></div><a class="button button-dark" href="rooms.php">Manage rooms <span aria-hidden="true">→</span></a></div><div class="stat-grid"><div class="stat-card"><small>ALL BOOKINGS</small><strong><?= (int) ($counts['total'] ?? 0) ?></strong><span>Recorded requests</span></div><div class="stat-card stat-highlight"><small>NEEDS YOUR EYE</small><strong><?= (int) ($counts['pending'] ?? 0) ?></strong><span>Pending requests</span></div><div class="stat-card"><small>CONFIRMED</small><strong><?= (int) ($counts['confirmed'] ?? 0) ?></strong><span>Upcoming stays</span></div></div><div class="table-heading"><div><p class="eyebrow">Guest requests</p><h2>Booking list</h2></div><span class="muted"><?= count($bookings) ?> total</span></div><?php if (!$bookings): ?><div class="empty-state"><strong>No bookings to show yet.</strong><p>New guest requests will appear here.</p></div><?php else: ?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Guest</th><th>Room and stay</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><strong><?= e($booking['guest_name']) ?></strong><small><?= e($booking['email']) ?></small></td><td><strong><?= e($booking['room_name']) ?></strong><small><?= e(date('M j', strtotime($booking['check_in']))) ?> – <?= e(date('M j, Y', strtotime($booking['check_out']))) ?> · <?= (int) $booking['guest_count'] ?> guests</small></td><td><?= money($booking['total_amount']) ?></td><td><span class="status status-<?= e($booking['booking_status']) ?>"><?= e(ucfirst($booking['booking_status'])) ?></span></td><td><?php if ($booking['booking_status'] !== 'cancelled'): ?><div class="action-buttons"><form method="post" action="booking-action.php"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int) $booking['booking_id'] ?>"><input type="hidden" name="action" value="confirm"><button class="mini-button" type="submit" <?= $booking['booking_status'] === 'confirmed' ? 'disabled' : '' ?>>Confirm</button></form><form method="post" action="booking-action.php"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int) $booking['booking_id'] ?>"><input type="hidden" name="action" value="cancel"><button class="mini-button mini-muted" type="submit" data-confirm="Cancel this reservation?">Cancel</button></form></div><?php else: ?><span class="muted">Closed</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require dirname(__DIR__) . '/includes/footer.php'; ?>
